 async editCopy(takeId:string,patch:CopyEdit){return this.store.edit(p=>{const take=p.hero!.takes.find(t=>t.id===takeId);if(!take)throw Error('Choose a saved photograph.');p.creative??={version:1,plans:[]};p.creative.adDrafts??={};const copy={...copyFor(p,take),...patch};p.creative.adDrafts[takeId]=copy;p.creative.adDraft={takeId,copy};});}
