   const take=selected.id==='klein'?await this.generateScene(planId,plan,p.attempt!.id):selected.id==='product-safe'?await this.generateProductSafe(planId,plan,selected.reason):await this.creative.generate(p.id,planId,selected.id==='zimage'?'zimage':'qwen');
